mapper.select:
SELECT ar.id, ar.module, u.username, u.id AS student_id, -- 假设 student_id 来自 user 表的 id u.major, -- 假设 major 来自 user 表 u.grade, -- 假设 grade 来自 user 表 ar.title, ar.description, ar.category, ar.score, ar.status, ar.teacher_comment, ar.create_time AS createTime, ar.update_time AS updateTime, GROUP_CONCAT( am.image_list SEPARATOR ',' -- 使用逗号作为分隔符 ) AS imageListStr -- 将图片路径聚合为一个字符串 FROM apply_record ar INNER JOIN user u ON ar.student_id = u.id -- 关联用户表 LEFT JOIN apply_material am ON ar.id = am.apply_id -- 左关联材料表，保证没有材料的申请也能查出
AND u.username = #{username}
AND ar.title = #{title}
AND ar.module = #{module}
AND ar.category = #{category}
GROUP BY ar.id, u.id -- 按申请ID和用户ID分组，聚合图片路径 ORDER BY ar.update_time DESC

SELECT ar.id, u.username, u.id AS student_id, u.major, u.grade, ar.title, ar.description, ar.category, ar.score, ar.status, ar.teacher_comment, ar.create_time AS createTime, ar.update_time AS updateTime, GROUP_CONCAT(am.image_list SEPARATOR ',') AS imageListStr FROM apply_record ar INNER JOIN user u ON ar.student_id = u.id INNER JOIN teacher_student ts ON ts.student_id = u.id LEFT JOIN apply_material am ON ar.id = am.apply_id
ts.teacher_id = #{teacherId}
AND u.username LIKE CONCAT('%', #{username}, '%')
AND ar.status = #{status}
GROUP BY ar.id, u.id ORDER BY ar.update_time DESC

SELECT image_path
FROM apply_material
WHERE apply_id = #{applyId}
